sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float c1active;
uniform float c1mode;
layout(color) uniform half4 c1color;
uniform float c1threshold;
uniform float c1feather;
uniform float c1luma;
uniform float c2active;
uniform float c2mode;
layout(color) uniform half4 c2color;
uniform float c2threshold;
uniform float c2feather;
uniform float c2luma;
uniform float c3active;
uniform float c3mode;
layout(color) uniform half4 c3color;
uniform float c3threshold;
uniform float c3feather;
uniform float c3luma;
uniform float c4active;
uniform float c4mode;
layout(color) uniform half4 c4color;
uniform float c4threshold;
uniform float c4feather;
uniform float c4luma;
uniform float showMask;
float3 yuv(float3 c) {
    float y = dot(c, float3(0.299, 0.587, 0.114));
    return float3(y, 0.492 * (c.b - y), 0.877 * (c.r - y));
}
float keep(float3 p, half4 key, float threshold, float feather, float luma) {
    if (key.a <= 0.0) return 1.0;
    float3 e = yuv(p) - yuv(float3(key.rgb));
    float d = length(float3(luma * e.x, e.yz));
    float soft = max(feather, 0.0001);
    return clamp((d - threshold + soft) / soft, 0.0, 1.0);
}
void slot(float3 p, float active, float mode, half4 key, float threshold, float feather, float luma, inout float cut, inout float hold) {
    if (active < 0.5) return;
    float k = keep(p, key, threshold, feather, luma);
    if (mode > 0.5) hold = max(hold, 1.0 - k); else cut = min(cut, k);
}
half4 main(float2 coord) {
    half4 c = image.eval(coord);
    float3 p = float3(unpremul(c).rgb);
    float cut = 1.0, hold = 0.0;
    slot(p, c1active, c1mode, c1color, c1threshold, c1feather, c1luma, cut, hold);
    slot(p, c2active, c2mode, c2color, c2threshold, c2feather, c2luma, cut, hold);
    slot(p, c3active, c3mode, c3color, c3threshold, c3feather, c3luma, cut, hold);
    slot(p, c4active, c4mode, c4color, c4threshold, c4feather, c4luma, cut, hold);
    float a = max(cut, hold);
    if (showMask > 0.5) return half4(half(a * c.a), 0.0, 0.0, 1.0);
    return c * half(a);
}
